use std::{fs,path::Path,process::{Command,Stdio}};
fn main(){let dir=std::env::args().nth(1).unwrap();let root=Path::new(&dir);assert!(!root.exists());fs::create_dir(root).unwrap();let bin=std::env::current_exe().unwrap().with_file_name("repeatedbase-all13");for p in [97,257,509,1009]{let s=Command::new(&bin).arg(p.to_string()).stdout(Stdio::from(fs::File::create(root.join(format!("p{p}.stdout"))).unwrap())).stderr(Stdio::from(fs::File::create(root.join(format!("p{p}.stderr"))).unwrap())).status().unwrap();fs::write(root.join(format!("p{p}.status")),format!("exit={:?}\n",s.code())).unwrap();assert!(s.success(),"registered_field_failed p={p}");println!("CASE_PASS p={p}");}println!("PASS runtime_prime_cohort=true cases=4 dlp_or_timing_claim=false");}
